		protected Note generateNewEntity() {
			Note entity = new Note( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),  null,  null,  null,  null,  null,  null,  null );
			
			return( entity );
		}

